// function pipe(value, ...fns) mein value aur functions do
// Agar value null/undefined hai: value return karo
// Agar fns empty hai: value return karo
// Warna har function se pass karo

solution:
function pipe(value, ...fns) {
  if (value === null || value === undefined) return value
  if (fns.length === 0) return value
  return fns.reduce((acc, fn) => fn(acc), value)
}
